def read(p):
    with io.open(p, encoding="utf-8") as f: return f.read()
def write(p, s):
    if DRY: return
    with io.open(p, "w", encoding="utf-8") as f: f.write(s)

report = []
for fn, (tbl_rows, untried) in SECTIONS.items():
    p = os.path.join(D, fn); s = read(p)
    lines = s.split("\n")
    hits = [i for i, l in enumerate(lines) if l.strip() == ANCHOR]
    assert len(hits) == 1, f"{fn}: anchor '{ANCHOR}' occurs {len(hits)} times (need exactly 1)"
    assert not any(l.startswith("## Instruments") or l.startswith("## Untried") for l in lines), f"{fn}: a section already exists"
    block = HDR_I + "\n\n" + TBL + tbl_rows + "\n" + HDR_U + "\n\n" + untried + "\n"
    i = hits[0]
    new = "\n".join(lines[:i]) + "\n" + block + "\n".join(lines[i:])
    write(p, new)
    n_rows = tbl_rows.count("\n"); n_unt = untried.count("\n- **") + (1 if untried.startswith("- **") else 0)
    report.append((fn, i + 1, n_rows, n_unt))

p = os.path.join(D, C2); s = read(p); lines = s.split("\n")
assert sum(1 for l in lines if l.startswith("## Instruments")) == 1 and sum(1 for l in lines if l.startswith("## Untried")) == 1, "C2: sections missing"
assert not any("[CORRECTION 2026-09-24" in l for l in lines), "C2: corrections already present"
for key, corr in C2_CORR:
    idx = [i for i, l in enumerate(lines) if l.startswith(key)]
    assert len(idx) == 1, f"C2: row key {key!r} occurs {len(idx)} times (need exactly 1)"
    lines.insert(idx[0] + 1, corr)
write(p, "\n".join(lines))
report.append((C2, "corrections", len(C2_CORR), 0))
for r in report: print(("DRY " if DRY else "") + str(r))
